package net.markandrew.kiosk.music;

import java.util.*;
import org.json.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.annotation.Config;
import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class) @Config(sdk=30)
public class GroupVolumeEvidenceTest {
    private JSONObject row(String id,int level)throws Exception{return new JSONObject().put("player_id",id).put("available",true).put("enabled",true).put("powered",true).put("volume_control","native").put("volume_level",level);}
    private final Set<String> members=new HashSet<>(Arrays.asList("private-local-id","private-peer-id"));
    private GroupVolumeEvidence evidence(JSONObject... rows){return new GroupVolumeEvidence(new JSONArray(Arrays.asList(rows)),members);}
    @Test public void maximumIsNotTheAverage()throws Exception{GroupVolumeEvidence e=evidence(row("private-local-id",23),row("private-peer-id",43));assertTrue(e.valid());assertEquals(43,e.maximum,0);}
    @Test public void poweredOffOrNonAdjustableMembersDoNotSetTheMaximum()throws Exception{assertEquals(23,evidence(row("private-local-id",23),row("private-peer-id",90).put("powered",false)).maximum,0);assertEquals(23,evidence(row("private-local-id",23),row("private-peer-id",90).put("volume_control","none")).maximum,0);}
    @Test public void missingPoweredMemberLevelIsNotInferredAsZero()throws Exception{JSONObject peer=row("private-peer-id",43);peer.remove("volume_level");assertFalse(evidence(row("private-local-id",23),peer).valid());}
    @Test public void participationAndMuteChangesRemainUnsafe()throws Exception{GroupVolumeEvidence before=evidence(row("private-local-id",42),row("private-peer-id",42));assertFalse(evidence(row("private-local-id",39),row("private-peer-id",39).put("powered",false)).sameParticipants(before));assertTrue(evidence(row("private-local-id",39),row("private-peer-id",39).put("volume_muted",true)).directionFailure(before,"private-local-id",-1).contains("mute flag changed"));}
    @Test public void anonymousMemberEvidenceContainsBothBeforeAndAfter()throws Exception{GroupVolumeEvidence before=evidence(row("private-local-id",42),row("private-peer-id",42)),after=evidence(row("private-local-id",39),row("private-peer-id",43));String report=after.summary(before,"private-local-id");assertTrue(report.contains("local 42.00% to 39.00%"));assertTrue(report.contains("member 2 42.00% to 43.00% (max)"));assertFalse(report.contains("private-"));}
    @Test public void localRoundingAllowanceDoesNotApplyToRemoteMember()throws Exception{GroupVolumeEvidence e=evidence(row("private-local-id",33),row("private-peer-id",32));assertTrue(e.onlyLocalMaximum("private-local-id"));assertTrue(e.resolutionFailure(30,"private-local-id",3).contains("remote step unknown"));}
    @Test public void receivedRangesAreDisplayedPerMemberAndDoNotExcuseAnOffGridMaximum()throws Exception{
        JSONObject local=row("private-local-id",25).put("device_info",new JSONObject().put("software_version",VolumeCapability.advertise("Music Assistant Plugin 0.9.52-dev",VolumeCapability.range(0,30))));
        JSONObject peer=row("private-peer-id",40).put("device_info",new JSONObject().put("software_version",VolumeCapability.advertise("Music Assistant Plugin 0.9.52-dev",VolumeCapability.range(0,15))));
        GroupVolumeEvidence e=evidence(local,peer);assertEquals(30,e.advertisedRanges.get("private-local-id").max);assertEquals(15,e.advertisedRanges.get("private-peer-id").max);
        String text=e.summary(e,"private-local-id");assertTrue(text.contains("3.33%"));assertTrue(text.contains("6.67%"));assertTrue(text.contains("connection snapshot"));assertFalse(text.contains("private-"));
        peer.put("volume_level",47);GroupVolumeEvidence higher=evidence(local,peer);assertFalse(higher.resolutionFailure(43,"private-local-id",3).isEmpty());
    }
    private JSONObject ranged(String id,int level,int min,int max)throws Exception{return row(id,level).put("device_info",new JSONObject().put("software_version",VolumeCapability.advertise("Music Assistant Plugin 0.9.52-dev",VolumeCapability.range(min,max))));}
    @Test public void tiedUnknownMaximumDoesNotBorrowCoarseRange()throws Exception{GroupVolumeEvidence before=evidence(row("private-local-id",40),ranged("private-peer-id",40,0,15)),after=evidence(row("private-local-id",40),ranged("private-peer-id",40,0,15));assertFalse(after.maximumMatches(before,43,"private-local-id",3));}
    @Test public void nonzeroMinimumAndExternalControlDoNotEnableQuantization()throws Exception{
        GroupVolumeEvidence a=evidence(row("private-local-id",25),ranged("private-peer-id",40,1,15));assertFalse(a.maximumMatches(a,43,"private-local-id",3));
        GroupVolumeEvidence b=evidence(row("private-local-id",25),ranged("private-peer-id",40,0,15).put("volume_control","external"));assertFalse(b.maximumMatches(b,43,"private-local-id",3));
    }
    @Test public void anOffGridMaximumIsNotExcusedByAWholeStepAllowance()throws Exception{GroupVolumeEvidence before=evidence(row("private-local-id",27),ranged("private-peer-id",47,0,15)),after=evidence(row("private-local-id",25),ranged("private-peer-id",42,0,15));assertFalse(after.maximumMatches(before,43,"private-local-id",3));}
    @Test public void incompatibleBaselineDoesNotEnableACoarseRangeAllowance()throws Exception{GroupVolumeEvidence before=evidence(row("private-local-id",17),ranged("private-peer-id",58,0,15)),after=evidence(row("private-local-id",16),ranged("private-peer-id",53,0,15));assertFalse(after.maximumMatches(before,56,"private-local-id",3));}
    @Test public void zeroTargetMustActuallyReachZero()throws Exception{GroupVolumeEvidence e=evidence(ranged("private-local-id",0,0,30),ranged("private-peer-id",1,0,15));assertFalse(e.maximumMatches(e,0,"private-local-id",3));}
    @Test public void inconsistentLocalStepDoesNotEnableItsAdvertisedGrid()throws Exception{GroupVolumeEvidence e=evidence(ranged("private-local-id",40,0,15),row("private-peer-id",20));assertFalse(e.maximumMatches(e,43,"private-local-id",1));}
    @Test public void previouslyQuieterKnownMemberMayJoinAnExplainedUnchangedMaximum()throws Exception{GroupVolumeEvidence before=evidence(ranged("private-local-id",37,0,30),ranged("private-peer-id",40,0,15)),after=evidence(ranged("private-local-id",40,0,30),ranged("private-peer-id",40,0,15));assertTrue(after.unchangedMaximumExplained(before,43,"private-local-id",3));assertTrue(after.maximumMatches(before,43,"private-local-id",3));assertTrue(after.resolutionFailure(before,43,"private-local-id",3).isEmpty());assertTrue(after.directionFailure(before,"private-local-id",1).isEmpty());}
    @Test public void newlyTiedUnknownMemberStillCannotBorrowCoarseRange()throws Exception{GroupVolumeEvidence before=evidence(row("private-local-id",37),ranged("private-peer-id",40,0,15)),after=evidence(row("private-local-id",40),ranged("private-peer-id",40,0,15));assertTrue(after.unchangedMaximumExplained(before,43,"private-local-id",3));assertFalse(after.maximumMatches(before,43,"private-local-id",3));}
    @Test public void allUnchangedStillHasNoIndependentDirectionalEvidence()throws Exception{GroupVolumeEvidence e=evidence(ranged("private-local-id",40,0,30),ranged("private-peer-id",40,0,15));assertFalse(e.unchangedMaximumExplained(e,43,"private-local-id",3));assertFalse(e.maximumMatches(e,43,"private-local-id",3));}
    @Test public void newTieDoesNotExcuseAnUnexplainedOriginalMaximum()throws Exception{GroupVolumeEvidence before=evidence(ranged("private-local-id",37,0,30),ranged("private-peer-id",40,0,15)),after=evidence(ranged("private-local-id",40,0,30),ranged("private-peer-id",40,0,15));assertFalse(after.unchangedMaximumExplained(before,47,"private-local-id",3));assertFalse(after.maximumMatches(before,47,"private-local-id",3));}
    @Test public void newTieWithChangedRangeOrInconsistentStepStillRejects()throws Exception{GroupVolumeEvidence before=evidence(ranged("private-local-id",37,0,30),ranged("private-peer-id",40,0,15)),after=evidence(ranged("private-local-id",40,0,60),ranged("private-peer-id",40,0,15));assertFalse(after.maximumMatches(before,43,"private-local-id",3));GroupVolumeEvidence consistent=evidence(ranged("private-local-id",40,0,30),ranged("private-peer-id",40,0,15));assertFalse(consistent.maximumMatches(before,43,"private-local-id",1));}
    @Test public void upwardTargetCrossesEveryKnownGridWithSmallestAdjustment()throws Exception{GroupVolumeEvidence e=evidence(ranged("private-local-id",20,0,30),ranged("private-peer-id",20,0,15));assertEquals(24,e.relativeTarget(3,"private-local-id",3));assertEquals(27,e.relativeTarget(7,"private-local-id",3));}
    @Test public void downwardTargetCrossesEveryKnownGridWithSmallestAdjustment()throws Exception{GroupVolumeEvidence e=evidence(ranged("private-local-id",23,0,30),ranged("private-peer-id",27,0,15));assertEquals(23,e.relativeTarget(-3,"private-local-id",3));}
    @Test public void unknownRangesKeepNominalTarget()throws Exception{GroupVolumeEvidence e=evidence(ranged("private-local-id",20,0,30),row("private-peer-id",20));assertEquals(23,e.relativeTarget(3,"private-local-id",3));}
    @Test public void inconsistentStepAndNonNativeControlKeepNominalTarget()throws Exception{GroupVolumeEvidence e=evidence(ranged("private-local-id",20,0,30),ranged("private-peer-id",20,0,15));assertEquals(23,e.relativeTarget(3,"private-local-id",1));GroupVolumeEvidence external=evidence(ranged("private-local-id",20,0,30),ranged("private-peer-id",20,0,15).put("volume_control","external"));assertEquals(23,external.relativeTarget(3,"private-local-id",3));}
    @Test public void offGridBaselineDoesNotEnableTargetExpansion()throws Exception{GroupVolumeEvidence e=evidence(ranged("private-local-id",20,0,30),ranged("private-peer-id",22,0,15));assertEquals(25,e.relativeTarget(3,"private-local-id",3));}
    @Test public void zeroDeltaAndClampedEndpointsStayUnchanged()throws Exception{GroupVolumeEvidence zero=evidence(ranged("private-local-id",0,0,30),ranged("private-peer-id",0,0,15)),full=evidence(ranged("private-local-id",100,0,30),ranged("private-peer-id",100,0,15));assertEquals(0,zero.relativeTarget(0,"private-local-id",3));assertEquals(0,zero.relativeTarget(-3,"private-local-id",3));assertEquals(100,full.relativeTarget(3,"private-local-id",3));assertEquals(100,zero.relativeTarget(200,"private-local-id",3));assertEquals(0,full.relativeTarget(-200,"private-local-id",3));}
    @Test public void lowerMemberGridAlsoParticipatesBecauseCachedReferenceIsUnknown()throws Exception{GroupVolumeEvidence e=evidence(ranged("private-local-id",40,0,30),ranged("private-peer-id",27,0,15));assertEquals(44,e.relativeTarget(3,"private-local-id",3));}
    @Test public void singleKnownFineGridDoesNotEnlargeAWorkingTarget()throws Exception{GroupVolumeEvidence e=evidence(ranged("private-local-id",20,0,30),ranged("private-peer-id",20,0,30));assertEquals(23,e.relativeTarget(3,"private-local-id",3));}
    @Test public void quieterStationaryMemberMayTieAnActuallyDescendingMaximum()throws Exception{GroupVolumeEvidence before=evidence(ranged("private-local-id",20,0,30),ranged("private-peer-id",27,0,15)),after=evidence(ranged("private-local-id",20,0,30),ranged("private-peer-id",20,0,15));assertTrue(after.maximumMatches(before,23,"private-local-id",3));assertTrue(after.directionFailure(before,"private-local-id",-1).isEmpty());assertTrue(after.resolutionFailure(before,23,"private-local-id",3).isEmpty());}
    @Test public void downwardTieStillRequiresItsOwnRangeAndTheOriginalMaximumRange()throws Exception{GroupVolumeEvidence before=evidence(row("private-local-id",20),ranged("private-peer-id",27,0,15)),after=evidence(row("private-local-id",20),ranged("private-peer-id",20,0,15));assertFalse(after.maximumMatches(before,23,"private-local-id",3));GroupVolumeEvidence beforeUnknown=evidence(ranged("private-local-id",20,0,30),row("private-peer-id",27)),afterUnknown=evidence(ranged("private-local-id",20,0,30),row("private-peer-id",20));assertFalse(afterUnknown.maximumMatches(beforeUnknown,23,"private-local-id",3));}
    @Test public void downwardTieDoesNotExcuseUnchangedOriginalMaximum()throws Exception{GroupVolumeEvidence e=evidence(ranged("private-local-id",20,0,30),ranged("private-peer-id",27,0,15));assertFalse(e.maximumMatches(e,23,"private-local-id",3));}
    @Test public void downwardTieStillRejectsWrongOriginalTargetAndChangedRange()throws Exception{GroupVolumeEvidence before=evidence(ranged("private-local-id",20,0,30),ranged("private-peer-id",27,0,15)),after=evidence(ranged("private-local-id",20,0,30),ranged("private-peer-id",20,0,15));assertFalse(after.maximumMatches(before,13,"private-local-id",3));GroupVolumeEvidence changed=evidence(ranged("private-local-id",20,0,60),ranged("private-peer-id",20,0,15));assertFalse(changed.maximumMatches(before,23,"private-local-id",3));}
    @Test public void downwardTieCannotExcuseOppositeLocalMovementOrMuteChange()throws Exception{GroupVolumeEvidence before=evidence(ranged("private-local-id",17,0,30),ranged("private-peer-id",27,0,15)),after=evidence(ranged("private-local-id",20,0,30),ranged("private-peer-id",20,0,15));assertFalse(after.maximumMatches(before,23,"private-local-id",3));GroupVolumeEvidence quiet=evidence(ranged("private-local-id",20,0,30),ranged("private-peer-id",27,0,15)),muted=evidence(ranged("private-local-id",20,0,30).put("volume_muted",true),ranged("private-peer-id",20,0,15));assertFalse(muted.maximumMatches(quiet,23,"private-local-id",3));}
}
